        var inventory = state.Society.Society.Inventory;
        for (var index = 0; index < 3; index++) inventory = InventoryAuthority.AddLot(inventory, $"collect-model-{index}", kind, actor, 1, storageBuildingId: House);
        var provider = new CollectionChoices(DecisionProviderKind.LargeLanguageModel);
