    private static WorldRuntimeState Prepared(bool distant = false)
    {
        var state = WorldRuntimeCodec.Decode(Generated.Value);
        var actor = Actor(state);
        state = WithInventory(state, state.Society.Society.Inventory with
        {
            Lots = state.Society.Society.Inventory.Lots.Where(lot => lot.OwnerId != actor).ToArray(),
        });
        var house = state.WorldSimulation!.Buildings.Single(building => building.InstanceId == House);
        var occupied = state.Agents.Where(person => person.AgentId != actor).Select(person => person.Position).ToHashSet();
        bool Clear(GridPoint point) => state.Map.IsPassable(point) && !occupied.Contains(point) &&
            state.Map.Resources.All(resource => resource.Position != point) && state.Map.MapObjects.All(item => item.Position != point);
        var position = distant ? (from near in state.Map.FootNeighbors(house.Position)
                                  where Clear(near)
                                  from far in state.Map.FootNeighbors(near)
                                  where Clear(far) && state.Map.FootDistance(far, house.Position) >= 2
                                  select far).First() : house.Position;
        return state with
        {
            JevEnabled = true,
            Agents = state.Agents.Select(person => person with
            {
                Position = person.AgentId == actor ? position : person.Position,
                FullnessBasisPoints = 10_000,
                Equipment = person.AgentId == actor ? null : person.Equipment,
                LastDecisionContext = null,
            }).ToArray(),
        };
    }

    private static string Actor(WorldRuntimeState state) =>
        state.Society.Society.Agents.First(person => person.HouseholdId == Household).Id;
    private static WorldRuntimeState WithInventory(WorldRuntimeState state, InventoryCheckpoint inventory) =>
        state with { Society = state.Society with { Society = state.Society.Society with { Inventory = StockHoldTestState.Custody(inventory) } } };
    private static WorldRuntime Restore(WorldRuntimeState state) => WorldRuntime.Restore(state, _ => new CollectionChoices());
    private static OwnerInstructionReceipt Submit(WorldRuntime world, string actor, string key, string text, bool queue = false) =>
        world.SubmitInstruction(new(key, "owner:test", actor, OwnerInstructionKind.Order, text, Queue: queue));
    private static OrderTask Order(WorldRuntime world, OwnerInstructionReceipt receipt) =>
        world.ExportState().Instructions!.Single(item => item.InstructionId == receipt.InstructionId).Task!;

    private sealed class CollectionChoices(DecisionProviderKind kind = DecisionProviderKind.Deterministic, bool hold = false) : IDecisionProvider
    {
        public DecisionProviderKind Kind => kind;
        public Task? EntryGate { get; set; }
        public ConcurrentQueue<AgentObservation> Requests { get; } = new();
        public InlineCompletionSource<CognitionDecisionRequest> Invoked { get; } = new(TaskCreationOptions.None);
        public InlineCompletionSource<AgentObservation> Started { get; } = new(TaskCreationOptions.None);
        public InlineCompletionSource<bool> Release { get; } = new(TaskCreationOptions.None);
        public InlineCompletionSource<CognitionDecisionResponse> Returned { get; } = new(TaskCreationOptions.None);
        public long ProviderEpoch => 0;
        public async ValueTask<CognitionDecisionResponse> DecideAsync(CognitionDecisionRequest request, CancellationToken cancellationToken = default)
        {
            if (hold) Invoked.TrySetResult(request);
            if (EntryGate is { } entry) await entry;
            request.Validate();
            Requests.Enqueue(request.Observation);
            var held = hold && Requests.Count == 1 && request.Observation.OperativeOrderInstructionId is not null;
            if (held)
            {
                Started.TrySetResult(request.Observation);
                await Release.Task;
            }
            var selected = request.Observation.Candidates.FirstOrDefault(candidate => candidate.Id is "collect_material" or "collect_food" or "collect_equipment")?.Id ?? "safe_idle";
            var response = new CognitionDecisionResponse(request.RequestId, request.Observation.AgentId,
                Kind, request.ProviderEpoch, request.Observation.RunEpoch, request.Observation.DecisionGeneration,
                request.Observation.ObservationDigest, selected, 1, new Dictionary<string, double> { [selected] = 1 });
            if (held) Returned.TrySetResult(response);
            return response;
        }
    }
}

