    [Theory]
    [InlineData("wood")]
    [InlineData("basket")]
    public async Task StorageOrderCountsExactQuantitiesAcrossLotsQueueAndReplay(string kind)
    {
        var state = Prepared();
        var actor = Actor(state);
        var inventory = InventoryAuthority.AddLot(state.Society.Society.Inventory, "storage-a", kind, actor, 2);
        inventory = InventoryAuthority.AddLot(inventory, "storage-b", kind, actor, 2);
        using var world = Restore(WithInventory(state, inventory));
        var first = Submit(world, actor, "three", $"store three {kind}");
        var second = Submit(world, actor, "remaining", $"store {kind}", queue: true);
        world.Pause();
        Assert.False((await world.AdvanceOneTickAsync()).Advanced);
        world.Resume();
        var before = WorldRuntimeCodec.Encode(world.ExportState());
        Assert.False((await world.AdvanceOneTickAsync(() => false)).Advanced);
        Assert.Equal(before, WorldRuntimeCodec.Encode(world.ExportState()));
        Assert.True((await world.AdvanceOneTickAsync()).Advanced);
        Assert.Equal(("doing", 2), (Order(world, first).Status, Order(world, first).CompletedUnits));
        Assert.Equal("queued", Order(world, second).Status);
        using var restored = Restore(WorldRuntimeCodec.Decode(WorldRuntimeCodec.Encode(world.ExportState())));
        Assert.True((await world.AdvanceOneTickAsync()).Advanced);
        Assert.True((await restored.AdvanceOneTickAsync()).Advanced);
        Assert.Equal(("finished", 3), (Order(world, first).Status, Order(world, first).CompletedUnits));
        Assert.Equal(1, world.Society.Inventory.GetLot("storage-b").Quantity);
        Assert.Null(world.Society.Inventory.GetLot("storage-b").StorageBuildingId);
        for (var tick = 0; tick < 3; tick++)
        {
            Assert.True((await world.AdvanceOneTickAsync()).Advanced);
            Assert.True((await restored.AdvanceOneTickAsync()).Advanced);
            Assert.Equal(WorldRuntimeCodec.Encode(world.ExportState()), WorldRuntimeCodec.Encode(restored.ExportState()));
        }
        Assert.Equal("finished", Order(restored, second).Status);
        Assert.Equal(4, restored.Society.Inventory.Lots.Where(lot => lot.OwnerId == actor && lot.ItemKind == kind &&
            lot.StorageBuildingId == House).Sum(lot => lot.Quantity));
        Assert.Equal(3, restored.ExportState().Events.Count(item => item.Kind == "personal_goods_stored"));
    }

